args.command:
python3 -c "
from PIL import Image
img = Image.open('/home/robot/captures/wrist_002.png')
# Save as text representation at higher resolution
img_small = img.resize((80, 60))
for y in range(60):
    line = ''
    for x in range(80):
        r, g, b = img_small.getpixel((x, y))
        brightness = (r + g + b) // 3
        if brightness > 200:
            line += '#'
        elif brightness > 150:
            line += '+'
        elif brightness > 100:
            line += '.'
        elif brightness > 50:
            line += ':'
        else:
            line += ' '
    print(line)
"

